
import './App.css';
import React from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
} from "react-router-dom";
import CentralHome from './components/HomeClients/CentralHome';
import Service1 from './components/services/FreeVersion/Free Version/src/Service1'
import Barnav from './components/HomeClients/Barnav';
import { useState } from 'react';
import AdminsHome from './components/HomeAdmins/AdminsHome';
import Admin from './components/services/FreeVersion/Free Version/src/components/AdminFrontend/Admin'
function App() {
// APIS Y IPS DE LOS SERVICIOS

const api1 = "https://service1-example-freeversion.onrender.com"
const ip1 = "190.151.204.235"



// visibilidades

const [centralVisibility, setCentralVisibility] = useState(true)
const [visibilityFree, setVisibilityFree] = useState(false)
const [visibilityCurrent, setVisibilityCurrent] = useState(false)
const [visibilityPremium, setVisibiliyPremium] = useState(false)
const [loginVisibility, setLoginVisibility] = useState(false)

// visibility functions


const centralVisibilityFunction = (e) => {
  e.preventDefault()
  setCentralVisibility(true)
  setVisibilityFree(false)
  setVisibilityCurrent(false)
  setVisibiliyPremium(false)
  
  setLoginVisibility(false)
}

const freeVisibilityFunction = (e) => {
  e.preventDefault()
  setCentralVisibility(false)
  setVisibilityFree(true)
  setVisibilityCurrent(false)
  setVisibiliyPremium(false)

  setLoginVisibility(false)
}

const currentVisibilityFunction = (e) =>
{
  e.preventDefault()
  setCentralVisibility(false)
  setVisibilityFree(false)
  setVisibilityCurrent(true)
  setVisibiliyPremium(false)

  setLoginVisibility(false)
}



const premiumVisibilityFunction = (e) => {
  e.preventDefault()
  setCentralVisibility(false)
  setVisibilityFree(false)
  setVisibilityCurrent(false)
  setVisibiliyPremium(true)
  setLoginVisibility(false)
}

const LoginVisibilityFunction = (e) => {
  e.preventDefault()
  setCentralVisibility(false)
  setVisibilityFree(false)
  setVisibilityCurrent(false)
  setVisibiliyPremium(false)
setLoginVisibility(true)
}
 const [visibilityClientFrontend, setVisibilityClientFrontend] = useState(true)
  const [securityAdmin, setSecurityAdmin] = useState(false)
const [admin, setAdmin] = useState(false)


const [barnavState, setBarnavState] = useState(true)
const [consoleAdmin, setConsoleAdmin] = useState([])





  return (
    <div className="central-App">
      <Router>
       {barnavState && <Barnav   LoginVisibilityFunction={LoginVisibilityFunction} premiumVisibilityFunction={premiumVisibilityFunction} currentVisibilityFunction={currentVisibilityFunction} freeVisibilityFunction={freeVisibilityFunction} centralVisibilityFunction={centralVisibilityFunction} />
       } <Routes>
        {/* HOME CENTRAL */}
          <Route path="/"  element={<CentralHome admin={admin} setAdmin={setAdmin} loginVisibility={loginVisibility} setLoginVisibility={setLoginVisibility} visibilityCurrent={visibilityCurrent} setVisibilityCurrent={setVisibilityCurrent} centralVisibility={centralVisibility} setCentralVisibility={setCentralVisibility} visibilityFree={visibilityFree} setVisibilityFree={setVisibilityFree} visibilityPremium={visibilityPremium} setVisibiliyPremium={setVisibiliyPremium} />} />
      
                 {/*ADMINISTRADOR CENTRAL  */}
                 <Route path="/admin" element={admin && <AdminsHome setBarnavState={setBarnavState} />} />
      
          {/* SERVICIOS */}

          {/* SERVICIO1 */}
          <Route path="/service1/*"   element={<Service1 ip1={ip1} api1={api1} consoleAdmin={consoleAdmin} setConsoleAdmin={setConsoleAdmin} securityAdmin={securityAdmin} setSecurityAdmin={setSecurityAdmin} setVisibilityClientFrontend={setVisibilityClientFrontend} visibilityClientFrontend={visibilityClientFrontend} setBarnavState={setBarnavState} />} />
          <Route path="/service1/admin"  element={<Admin  api1={api1} setVisibilityClientFrontend={setVisibilityClientFrontend} securityAdmin={securityAdmin} setConsoleAdmin={setConsoleAdmin} consoleAdmin={consoleAdmin} />} />
   
          {/* SERVICIO2 */}

   
        </Routes>
        </Router>
          </div>
  );
}

export default App;
